public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path by the '/' separator
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Create a list to hold the final path parts
    List<String> resultParts = new ArrayList<>(Arrays.asList(pathParts));

    // Process each part of the relative path
    for (String part : relativePathParts) {
        if (part.equals("..")) {
            // Move up one level in the directory structure
            if (!resultParts.isEmpty()) {
                resultParts.remove(resultParts.size() - 1);
            }
        } else if (!part.isEmpty() && !part.equals(".")) {
            // Add the part to the result
            resultParts.add(part);
        }
    }

    // Join the result parts into a single string with '/' separators
    return String.join("/", resultParts);
}
